import type { ProductId } from "./product";

/**
 * Reference product description, generated by AI ahead of time (batch, not realtime) and
 * stored separately. Flagged as "AI-generated" in the catalog — a human reviews and edits
 * it if needed.
 */
export interface ProductDescription {
  readonly productId: ProductId;
  readonly text: string;
  /** Presumed source (official site / search) — verified by a human. */
  readonly sourceUrl: string | null;
}
